# Generalized poisson
stancode <- "functions {
  real generalized_poisson(int n, real theta, real lambda) {
    return log(theta)
    + (n - 1) * log(theta + n * lambda)
    - lgamma(n + 1)
    - n * lambda
    - theta;
  }
}
data {
  int<lower=0> N;
